  function singleStageAt(p,s,index){let background=null,backgroundBlock=null,portrait=null,cgBlock=null,cgControlBlock=null,visualBlock=null;for(let i=0;i<=index;i++){const b=s.blocks[i];if(!b)continue;if(b.type==='background'){background=p.assets.find(a=>a.id===b.asset&&a.type==='image');backgroundBlock=b;visualBlock=b}if(b.type==='cg'){cgControlBlock=b;cgBlock=b.visible===false?null:b;visualBlock=b}if(b.type==='portrait'){portrait={...b,hidden:b.visible===false}}if(b.type==='dialogue'&&b.speaker&&!p.characters.find(c=>c.id===b.speaker)?.preserveStagePortrait){if(portrait?.speaker!==b.speaker)portrait={speaker:b.speaker,variant:'',position:p.characters.find(c=>c.id===b.speaker)?.portraitLayout?'custom':'center',hidden:false};if(b.variant){portrait.variant=b.variant;portrait.hidden=false}if(b.position)portrait.position=b.position;if(b.portraitLayout)portrait.portraitLayout={...b.portraitLayout};if(b.moveDuration!==undefined)portrait.moveDuration=b.moveDuration;if(b.moveEasing)portrait.moveEasing=b.moveEasing}}const c=p.characters.find(c=>c.id===portrait?.speaker),cg=cgBlock?p.assets.find(a=>a.id===cgBlock.asset&&a.type==='image'):null;return {background,backgroundBlock,portrait,character:c,portraitAsset:portrait?.hidden?null:portraitAsset(p,c,portrait?.variant),cg,cgBlock,cgControlBlock,visualBlock}}
