    function cueSpeaker(line,before=true){if(!line)return null;const label=line.trim().replace(/[：:]$/,'');if(before&&actorNames.has(label))return actorNames.get(label);const subject=names.find(name=>line.trim().startsWith(name)&&line.trim().slice(name.length, name.length+1)!=='们');if(!subject)return null;const tail=line.trim().slice(subject.length);if(before&&!/[：:]$/.test(line.trim()))return null;if(!before&&/[：:]$/.test(line.trim()))return null;return /(?:说道|说着|笑道|问道|答道|回道|喊道|回答|嘀咕|嘟囔|补充|思量|心想|暗想|低声说|开口说)/.test(tail)?actorNames.get(subject):null}
