      const opt=line.match(/^[\[【]选项[：:]\s*(.*?)\s*(?:→|->)\s*(.*?)[\]】]$/);if(opt){const last=current.blocks.at(-1);if(last?.type==='choice'){last.options.push({text:opt[1],targetName:opt[2],target:''});return}warnings.push(`第 ${n} 行：选项前没有分支，已保留原文。`);current.blocks.push(make('narration',{text:line}));return}
      const cmd=line.match(/^[\[【](背景|立绘|隐藏|音乐|跳转)[：:]\s*(.*)[\]】]$/);if(cmd){const [name,arg='',pos='',fit='',color='',scale='',moveMs='',moveEase='']=cmd[2].split('|').map(x=>x.trim());if(!name){warnings.push(`第 ${n} 行：指令缺少名称，已保留为旁白。`);current.blocks.push(make('narration',{text:line}));return}if(cmd[1]==='背景')current.blocks.push(make('background',{asset:/^#[a-f\d]{6}$/i.test(name)?'':findAsset(name,n),text:name,transition:effect(arg),duration:duration(pos||700),fit:['完整显示','contain'].includes(fit)?'contain':'cover',color:/^#[a-f\d]{6}$/i.test(name)?name:/^#[a-f\d]{6}$/i.test(color)?color:'#24372e'}));if(cmd[1]==='音乐')current.blocks.push(make('music',{asset:findAsset(name,n,'audio'),text:name}));if(cmd[1]==='立绘'||cmd[1]==='隐藏'){const c=findCharacter(name,n);if(roleMap[name]==='__narration__')current.blocks.push(make('narration',{text:line}));else current.blocks.push(make('portrait',{speaker:c?.id||'',sourceSpeaker:name,variant:variant(c,arg,n),position:position(pos),...(position(pos)==='custom'?{portraitLayout:portraitPlacement({portraitLayout:{x:fit||50,y:color||100,scale:scale||100}})}:{}),...(moveMs!==''?{moveDuration:portraitMotion({moveDuration:moveMs}).duration,moveEasing:portraitMotion({moveEasing:moveEase}).easing}:{}),visible:cmd[1]!=='隐藏',text:cmd[1]==='隐藏'?`隐藏 ${name}`:`${name} · ${arg||'默认'}`}))}if(cmd[1]==='跳转')current.blocks.push(make('jump',{targetName:name,target:'',text:'跳转场景'}));return}
